};

/// Represents a cardinal direction or block face.
pub const BlockDirection = enum(u8) {
    down,
    up,
    north,
    south,
    west,
    east,
};

/// Specialized data for shulker entities.
pub const ShulkerData = struct {
    attached_face: BlockDirection,
    peek_amount: u8,
    color: ?DyeColor,
};

/// Tagged variant holding specialized data for specific mob types.
pub const MobData = union(enum) {
    sheep: SheepData,
    wolf: WolfData,
    cat: CatData,
    villager: VillagerData,
    creeper: CreeperData,
    slime: SlimeData,
    enderman: EndermanData,
    iron_golem: IronGolemData,
    fox: FoxData,
    ageable: AgeableData,
    zombie: ZombieData,
    shulker: ShulkerData,
    generic,
};

/// Result of a raycast operation.
pub const RaycastResult = struct {
    /// The block position that was hit.
    pos: BlockPos,
    /// The face of the block that was hit.
    face: BlockDirection,
};

/// Detailed result of a block ray-trace operation.
pub const RayTraceBlockResult = struct {
    /// The block position that was hit.
    pos: BlockPos,
    /// The face of the block that was hit.
    face: BlockDirection,
    /// The exact hit coordinates in world space.
